def create_workbook():
    wb = Workbook()
    # ---- TestPlan Sheet ----
    ws_tp = wb.active
    ws_tp.title = "TestPlan"
    tp_cols = ["Index", "SS / Module", "Feature", "Test Case Name", "Speed", "Mode",
               "Memory Start Offset", "Memory End Offset", "Test Description",
               "Test Steps / Procedure", "Impacted Registers",
               "Validation / Acceptance Criteria", "Remarks",
               "Code Generation (Required / Not)"]
    hdr_font = Font(bold=True, color="FFFFFF")
    hdr_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    wrap = Alignment(wrap_text=True, vertical="top")
    for c, col_name in enumerate(tp_cols, 1):
        cell = ws_tp.cell(row=1, column=c, value=col_name)
        cell.font = hdr_font
        cell.fill = hdr_fill
        cell.alignment = wrap
    for r, row_data in enumerate(TESTPLAN_JSON, 2):
        ws_tp.cell(row=r, column=1, value=row_data.get("Index", "")).alignment = wrap
        ws_tp.cell(row=r, column=2, value=row_data.get("SS / Module", "")).alignment = wrap
        ws_tp.cell(row=r, column=3, value=row_data.get("Feature", "")).alignment = wrap
        ws_tp.cell(row=r, column=4, value=row_data.get("Test Case Name", "")).alignment = wrap
        ws_tp.cell(row=r, column=5, value=row_data.get("Speed", "")).alignment = wrap
        ws_tp.cell(row=r, column=6, value=row_data.get("Mode", "")).alignment = wrap
        ws_tp.cell(row=r, column=7, value=row_data.get("Memory Start Offset", "")).alignment = wrap
        ws_tp.cell(row=r, column=8, value=row_data.get("Memory End Offset", "")).alignment = wrap
        ws_tp.cell(row=r, column=9, value=row_data.get("Test Description", "")).alignment = wrap
        ws_tp.cell(row=r, column=10, value=row_data.get("Test Steps / Procedure", "")).alignment = wrap
        ws_tp.cell(row=r, column=11, value=row_data.get("Impacted Registers", "")).alignment = wrap
        ws_tp.cell(row=r, column=12, value=row_data.get("Validation / Acceptance Criteria", "")).alignment = wrap
        ws_tp.cell(row=r, column=13, value=row_data.get("Remarks", "")).alignment = wrap
        # Column 14 (Code Generation) left blank
    dv = DataValidation(type="list", formula1='"Required,Not Required"', allow_blank=True)
    dv.error = "Please select Required or Not Required"
    dv.errorTitle = "Invalid Entry"
    dv.prompt = "Select Code Generation option"
    dv.promptTitle = "Code Generation"
    for r in range(2, len(TESTPLAN_JSON) + 2):
        dv.add(ws_tp.cell(row=r, column=14))
    ws_tp.add_data_validation(dv)
    ws_tp.freeze_panes = "A2"
    for col in ws_tp.columns:
        max_len = 0
        col_letter = col[0].column_letter
        for cell in col:
            if cell.value:
                max_len = max(max_len, min(len(str(cell.value)), 80))
        ws_tp.column_dimensions[col_letter].width = min(max(max_len + 2, 12), 80)

    # ---- MetaData Sheet ----
    ws_md = wb.create_sheet("MetaData")
    md_cols = ["Test Case Name", "Meta Headers", "Meta Macros", "Meta Arrays",
               "Meta Types", "Meta Test Description", "Meta Test Steps / Procedure",
               "Meta Impacted Registers", "Meta Validation / Acceptance Criteria"]
    for c, col_name in enumerate(md_cols, 1):
        cell = ws_md.cell(row=1, column=c, value=col_name)
        cell.font = hdr_font
        cell.fill = hdr_fill
        cell.alignment = wrap
    for r, row_data in enumerate(META_JSON, 2):
        ws_md.cell(row=r, column=1, value=row_data.get("Test Case Name", "")).alignment = wrap
        ws_md.cell(row=r, column=2, value=row_data.get("Meta Headers", "")).alignment = wrap
        ws_md.cell(row=r, column=3, value=row_data.get("Meta Macros", "")).alignment = wrap
        ws_md.cell(row=r, column=4, value=row_data.get("Meta Arrays", "")).alignment = wrap
        ws_md.cell(row=r, column=5, value=row_data.get("Meta Types", "")).alignment = wrap
        ws_md.cell(row=r, column=6, value=row_data.get("Meta Test Description", "")).alignment = wrap
        ws_md.cell(row=r, column=7, value=row_data.get("Meta Test Steps / Procedure", "")).alignment = wrap
        ws_md.cell(row=r, column=8, value=row_data.get("Meta Impacted Registers", "")).alignment = wrap
        ws_md.cell(row=r, column=9, value=row_data.get("Meta Validation / Acceptance Criteria", "")).alignment = wrap
    ws_md.sheet_state = "veryHidden"
    ws_md.freeze_panes = "A2"
    for col in ws_md.columns:
        max_len = 0
        col_letter = col[0].column_letter
        for cell in col:
            if cell.value:
                max_len = max(max_len, min(len(str(cell.value)), 80))
        ws_md.column_dimensions[col_letter].width = min(max(max_len + 2, 12), 80)

    wb.save(FILENAME)
    print(f"Saved: {FILENAME}")
    return FILENAME

def validate_workbook(fn):
    assert os.path.exists(fn), "File not found"
    assert os.path.getsize(fn) > 0, "File empty"
    wb = load_workbook(fn)
    assert "TestPlan" in wb.sheetnames, "TestPlan sheet missing"
    assert "MetaData" in wb.sheetnames, "MetaData sheet missing"
    tp = wb["TestPlan"]
    assert tp.max_row - 1 == len(TESTPLAN_JSON), f"Row count mismatch: {tp.max_row-1} vs {len(TESTPLAN_JSON)}"
    md = wb["MetaData"]
    assert md.max_row - 1 == len(META_JSON), f"Meta row count mismatch: {md.max_row-1} vs {len(META_JSON)}"
    assert tp.cell(row=1, column=14).value == "Code Generation (Required / Not)", "Code Gen column missing"
    for r in range(2, len(TESTPLAN_JSON) + 2):
        assert tp.cell(row=r, column=14).value is None, f"Code Gen cell row {r} not blank"
    assert len(tp.data_validations.dataValidation) > 0, "No data validation found"
    print("Validation: PASSED")
    return True

def upload_to_github(fn):
    token = os.environ.get("GITHUB_TOKEN", "")
    if not token:
        print("GITHUB_TOKEN not set. Skipping upload."); return None, None
    path = f"{OUTPUT_DIR}/{fn}"
    url = f"https://api.github.com/repos/{OWNER}/{REPO}/contents/{path}"
    headers = {"Authorization": f"token {token}", "Accept": "application/vnd.github.v3+json"}
    # Check if file exists
    resp = requests.get(url, headers=headers, params={"ref": BRANCH})
    sha = resp.json().get("sha") if resp.status_code == 200 else None
    with open(fn, "rb") as f:
        content = base64.b64encode(f.read()).decode()
    payload = {"message": "Generated TestPlan Excel Workbook", "content": content, "branch": BRANCH}
    if sha:
        payload["sha"] = sha
    resp = requests.put(url, headers=headers, json=payload)
    if resp.status_code in (200, 201):
        data = resp.json()
        html_url = data.get("content", {}).get("html_url", "")
        commit_sha = data.get("commit", {}).get("sha", "")
        print(f"Uploaded: {html_url}")
        print(f"Commit SHA: {commit_sha}")
        return html_url, commit_sha
    else:
        print(f"Upload failed: {resp.status_code} {resp.text}")
        return None, None

if __name__ == "__main__":
    fn = create_workbook()
    ok = validate_workbook(fn)
    if ok:
        html_url, commit_sha = upload_to_github(fn)
        result = {
            "status": "SUCCESS" if commit_sha else "IN_PROGRESS",
            "output_file_path": f"{OUTPUT_DIR}/{fn}",
            "github_url": html_url or "",
            "filename": fn,
            "rows_testplan": len(TESTPLAN_JSON),
            "rows_metadata": len(META_JSON),
            "commit_sha": commit_sha or "",
            "validation": "PASSED"
        }
    else:
        result = {
            "status": "FAILURE",
            "output_file_path": "",
            "github_url": "",
            "filename": fn,
            "rows_testplan": 0,
            "rows_metadata": 0,
            "commit_sha": "",
            "validation": "FAILED"
        }
    print(json.dumps(result, indent=2))
